package br.com.admeclesial.interfaces.rest.financeiro; import br.com.admeclesial.application.financeiro.*; import br.com.admeclesial.domain.financeiro.Pagamento; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/v1/pagamentos") public class PagamentoRestController { final PagamentoApplicationService s; public PagamentoRestController(PagamentoApplicationService s){this.s=s;} @PostMapping public Pagamento criar(@Valid @RequestBody PagamentoRequest r){return s.criar(r);} @GetMapping public List<Pagamento> listar(){return s.listar();} }